insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('10-e558abc73f','aux-cm',10,'Las Mesas de Negociación quedarán válidamente constituidas cuando las organizaciones sindicales presentes representen, como mínimo:','["El 10 % de los miembros de los órganos unitarios de representación", "La totalidad de los miembros de los órganos unitarios de representación", "La mayoría absoluta de los miembros de los órganos unitarios de representación en el ámbito de que se trate", "Un tercio de los miembros de los órganos unitarios de representación en el ámbito de que se trate"]'::jsonb,2,'Art. 35.1 TREBEP','Ninguna de las partes puede superar quince miembros (art. 35.4).',null),
('11-93233294f4','aux-cm',11,'La prestación temporal de viudedad tiene una duración de:','["Seis meses", "Cinco años", "Un año", "Dos años"]'::jsonb,3,'Art. 222 TRLGSS','Se concede cuando no se reúnen los requisitos de la pensión de viudedad por el periodo de matrimonio.',null),
('10-4f9a330a04','aux-cm',10,'Los órganos de selección no podrán proponer el acceso a la condición de funcionario de un número superior de aprobados al de plazas convocadas:','["Salvo en la Administración Local, cuando lo acuerde el Pleno", "Salvo que la convocatoria prevea otra cosa", "En ningún caso, y cualquier propuesta que lo contravenga será nula de pleno derecho", "Salvo que lo solicite el tribunal"]'::jsonb,1,'Art. 61.8 TREBEP','Regla general con la excepción prevista.',null),
('13-592fb43728','aux-cm',13,'La Delegación del Gobierno contra la Violencia de Género, entre otras funciones:','["Dicta resoluciones vinculantes para los juzgados de violencia sobre la mujer", "Dirige y coordina a la policía judicial en las investigaciones de violencia de género y dicta instrucciones a los juzgados especializados", "Elabora la Macroencuesta de Violencia contra las Mujeres y está legitimada ante los órganos jurisdiccionales", "Impone sanciones administrativas a los agresores y dirige las investigaciones de la policía judicial en los casos más graves"]'::jsonb,2,'Art. 29 LO 1/2004','Formula las políticas públicas en materia de violencia de género.',null),
('9-97ea903062','aux-cm',9,'Si la demora en el pago por la Administración fuese superior a seis meses, el contratista tendrá derecho a:','["Ceder el contrato a un tercero sin necesidad de autorización del órgano de contratación", "Resolver el contrato y al resarcimiento de los perjuicios", "Una prórroga del contrato por un plazo igual al de la demora", "Suspender la ejecución, pero no resolver el contrato"]'::jsonb,1,'Art. 198.6 LCSP','Si la demora supera cuatro meses puede suspender el cumplimiento del contrato.',null),
('9-a411e21281','aux-cm',9,'La garantía complementaria que puede exigirse en casos especiales puede ser de hasta un 5 %, de modo que la garantía total pueda alcanzar:','["Un 15 % del precio del contrato", "Un 8 % del precio del contrato, IVA incluido", "Un 10 % del precio del contrato", "Un 20 % del precio del contrato"]'::jsonb,2,'Art. 107.2 LCSP','La garantía definitiva ordinaria es del 5 % y la complementaria hasta otro 5 %.',null),
('11-405d7f8b3e','aux-cm',11,'El derecho al percibo de las prestaciones a tanto alzado y por una sola vez caduca:','["A los cinco años, a contar desde el día siguiente a su notificación", "Nunca", "A los tres meses, a contar desde el día siguiente a su notificación", "Al año, a contar desde el día siguiente a su notificación"]'::jsonb,3,'Art. 54.1 TRLGSS','En las prestaciones periódicas, cada mensualidad caduca al año de su vencimiento.',null),
('13-b47c9c57ae','aux-cm',13,'Entre los criterios de actuación de las Administraciones en el empleo público, la LO 3/2007 incluye:','["Promover la presencia equilibrada de mujeres y hombres en los órganos de selección y valoración", "Suprimir los planes de igualdad", "Establecer cuotas obligatorias del 60 % de mujeres en todos los órganos de selección y valoración", "Reservar los puestos directivos a la persona más antigua"]'::jsonb,0,'Art. 51 d) LO 3/2007','También establecer medidas efectivas para eliminar cualquier discriminación retributiva.',null),
('15-b5d65c1b7f','aux-cm',15,'Según la Ley 6/2023, el órgano competente para imponer sanciones por infracciones muy graves es:','["La Dirección General competente", "El Ayuntamiento", "El Consejo de Gobierno", "La Consejería competente"]'::jsonb,2,'Art. 109 Ley 6/2023 CM','Leves: Dirección General; graves: Consejería.',null),
('7-f04410e574','aux-cm',7,'La cuestión de ilegalidad se plantea por el juez o tribunal mediante auto que deberá dictarse:','["Antes de dictar sentencia, dentro del plazo para dictarla y previa audiencia de las partes por diez días", "En el plazo de un mes desde la firmeza de la sentencia", "Dentro de los cinco días siguientes a que conste en las actuaciones la firmeza de la sentencia", "En el plazo de dos meses"]'::jsonb,2,'Art. 123.1 Ley 29/1998','Se plantea en cinco días desde la firmeza de la sentencia.',null),
('13-1370506967','aux-cm',13,'En los procedimientos (no penales) en que se aleguen actuaciones discriminatorias por razón de sexo, corresponde probar la ausencia de discriminación a:','["La persona demandante", "El Ministerio Fiscal", "La persona demandada", "El juez"]'::jsonb,2,'Art. 13.1 LO 3/2007','Es la inversión de la carga de la prueba; no se aplica a los procesos penales.','oct. 2026 · 1.er ejercicio'),
('11-22f9d98a27','aux-cm',11,'El derecho al reconocimiento de las prestaciones de la Seguridad Social prescribe, con carácter general, a los:','["Cuatro años, contados desde el día siguiente al hecho causante", "Cinco años, contados desde el día siguiente al hecho causante", "Diez años", "Un año, contado desde el día siguiente al hecho causante"]'::jsonb,1,'Art. 53.1 TRLGSS','Sin perjuicio de las excepciones legales.',null),
('10-10b7ce9645','aux-cm',10,'La excedencia por cuidado de un familiar hasta el segundo grado que no pueda valerse por sí mismo tiene una duración no superior a:','["Tres años", "Dos años", "Cinco años", "Un año"]'::jsonb,0,'Art. 89.4 TREBEP','Igual que la excedencia por cuidado de cada hijo.',null),
('10-2ff07a778f','aux-cm',10,'Si la incapacidad temporal impide disfrutar las vacaciones en el año natural, podrán disfrutarse una vez finalizada, siempre que no hayan transcurrido más de:','["Un año a partir del final del año en que se hayan originado", "Tres años", "Seis meses a partir del final del año en que se hayan originado", "Dieciocho meses a partir del final del año en que se hayan originado"]'::jsonb,3,'Art. 50.2 TREBEP','Las vacaciones no pueden sustituirse por una cuantía económica, salvo cese no voluntario.',null),
('10-fa3debe972','aux-cm',10,'En el permiso por nacimiento, ¿cuántas semanas inmediatas posteriores al parto son de descanso obligatorio?','["Dos semanas", "Seis semanas", "Diez semanas", "Cuatro semanas"]'::jsonb,1,'Art. 49 a) TREBEP','Las seis semanas posteriores al parto son obligatorias e ininterrumpidas.',null),
('9-c0785ad1a2','aux-cm',9,'La Administración tiene la obligación de abonar el precio dentro de los ___ siguientes a la fecha de aprobación de las certificaciones o documentos de conformidad:','["Noventa días", "Quince días", "Sesenta días", "Treinta días"]'::jsonb,3,'Art. 198.4 LCSP','Si se retrasa, debe abonar intereses de demora y la indemnización por costes de cobro.',null),
('9-2a15b516de','aux-cm',9,'Contra las actuaciones susceptibles de recurso especial en materia de contratación:','["No procederá la interposición de recursos administrativos ordinarios", "Cabe además recurso de alzada ante el titular del departamento ministerial", "Cabe recurso de reposición obligatorio, previo al recurso especial", "Cabe recurso extraordinario de revisión previo, en los supuestos del art. 125 de la Ley 39/2015"]'::jsonb,0,'Art. 44.5 LCSP','El recurso especial sustituye a los recursos ordinarios.',null),
('7-27ce69c01b','aux-cm',7,'La Sala de lo Contencioso-administrativo de la Audiencia Nacional conoce en única instancia de los recursos contra:','["Los actos de los Ayuntamientos de municipios de gran población", "Los actos del Consejo de Ministros, de las Comisiones Delegadas del Gobierno y del Consejo General del Poder Judicial, en todo caso", "Las disposiciones generales y los actos de los Ministros y Secretarios de Estado, en los términos del art. 11", "Las sentencias de los TSJ"]'::jsonb,2,'Art. 11.1 a) Ley 29/1998','También conoce de las apelaciones contra resoluciones de los Juzgados Centrales. Nota: desde el 31/12/2025 (LO 1/2025), los Juzgados de lo Contencioso-administrativo y los Juzgados Centrales se han transformado en Secciones de los Tribunales de Instancia y del Tribunal Central de Instancia, aunque la Ley 29/1998 mantiene la antigua denominación.',null),
('7-88f3cb0a1c','aux-cm',7,'En el procedimiento para la protección de los derechos fundamentales, la sentencia se dictará en el plazo de:','["Diez días desde que las actuaciones queden conclusas", "Un mes", "Veinte días desde la contestación", "Cinco días desde que las actuaciones queden conclusas"]'::jsonb,3,'Art. 121.1 Ley 29/1998','Es un procedimiento preferente y sumario.',null),
('11-6f77d68f15','aux-cm',11,'En caso de enfermedad común o accidente no laboral, el subsidio de incapacidad temporal se abona:','["Desde el primer día de baja", "Desde el día siguiente a la baja en el trabajo", "A partir del decimosexto día de baja, a cargo de la entidad gestora", "A partir del cuarto día de baja en el trabajo"]'::jsonb,3,'Art. 173.1 TRLGSS','Del cuarto al decimoquinto día el abono corresponde al empresario.',null),
('10-01e822e4db','aux-cm',10,'Es una falta muy grave según el art. 95.2 TREBEP:','["El descuido leve en el trabajo", "El abandono del servicio", "La falta de puntualidad ocasional", "Un retraso de diez minutos"]'::jsonb,1,'Art. 95.2 c) TREBEP','Otras faltas muy graves: desobediencia abierta, acoso laboral, etc.','nov. 2024 · 1.er ejercicio'),
('7-bb380e642c','aux-cm',7,'En la imposición de costas, la cantidad a satisfacer no podrá exceder de:','["6.000 euros por cada parte", "La cuantía total del proceso", "La mitad de la cuantía del proceso, salvo circunstancias que lo justifiquen", "La tercera parte de la cuantía del proceso, salvo circunstancias que lo justifiquen"]'::jsonb,3,'Art. 139.4 Ley 29/1998','Las pretensiones de cuantía indeterminada se valoran en 18.000 euros a estos efectos.',null),
('9-279ec25a0d','aux-cm',9,'¿Puede prorrogarse un contrato por consentimiento tácito de las partes?','["Sí, si lo autoriza el responsable del contrato", "Sí, siempre", "Sí, si es un contrato menor", "No, en ningún caso"]'::jsonb,3,'Art. 29.2 LCSP','La prórroga la acuerda el órgano de contratación y nunca es tácita.',null),
('7-04ac0c292d','aux-cm',7,'Con carácter general, es competente territorialmente el órgano jurisdiccional en cuya circunscripción:','["Lo elija libremente el recurrente en todo caso", "Tenga su domicilio el recurrente, en todo caso, cualquiera que sea la materia", "Tenga su sede el órgano que hubiera dictado la disposición o el acto impugnado", "Se haya publicado el acto"]'::jsonb,2,'Art. 14.1 Ley 29/1998','Es la regla primera del art. 14.',null),
('10-6acff6cb31','aux-cm',10,'La sanción de separación del servicio de los funcionarios solo podrá imponerse por:','["Faltas graves reiteradas en el plazo de un año", "Cualquier falta", "La comisión de faltas muy graves", "Faltas graves cometidas de forma reiterada"]'::jsonb,2,'Art. 96.1 a) TREBEP','En los interinos implica la revocación del nombramiento.',null),
('9-12601b622f','aux-cm',9,'Es una prohibición de contratar del art. 71.1:','["Haber sido adjudicatario de otro contrato con la misma Administración en los últimos tres años", "Tener menos de diez trabajadores", "Haber sido condenado mediante sentencia firme por determinados delitos, como cohecho o prevaricación", "No disponer de sede social en España"]'::jsonb,2,'Art. 71.1 a) LCSP','Otras: sanciones firmes, concurso, incumplimiento de obligaciones tributarias o de Seguridad Social…',null),
('11-265f101edb','aux-cm',11,'El subsidio por nacimiento y cuidado de menor consiste en un subsidio equivalente al:','["60 % de la base reguladora correspondiente", "75 % de la base reguladora durante las seis primeras semanas", "100 % de la base reguladora correspondiente", "75 % de la base reguladora de contingencias comunes"]'::jsonb,2,'Art. 179.1 TRLGSS','La base reguladora es la de incapacidad temporal por contingencias comunes.',null),
('10-0b84d6d852','aux-cm',10,'La duración del mandato de los Delegados de Personal y de las Juntas de Personal es de:','["Tres años", "Cinco años", "Dos años", "Cuatro años"]'::jsonb,3,'Art. 42 TREBEP','Pueden ser reelegidos en sucesivos procesos electorales.',null),
('9-443b118229','aux-cm',9,'Cada una de las penalidades no podrá ser superior al ___ del precio del contrato, ni el total superar el 50 %:','["5 %", "20 %", "10 %", "30 %"]'::jsonb,2,'Art. 192.1 LCSP','Límites de las penalidades contractuales.',null),
('7-25cd890f15','aux-cm',7,'NO es admisible el recurso contencioso-administrativo respecto de:','["Los actos que sean reproducción de otros anteriores definitivos y firmes", "Los actos que pongan fin a la vía administrativa", "La inactividad de la Administración", "Las actuaciones materiales de la Administración que constituyan vía de hecho"]'::jsonb,0,'Art. 28 Ley 29/1998','Tampoco contra los actos confirmatorios de actos consentidos por no haber sido recurridos en tiempo y forma.',null),
('11-22d8dde08e','aux-cm',11,'Tienen derecho a la pensión de orfandad, con carácter general, los hijos del causante:','["Menores de dieciocho años solamente", "Menores de dieciséis años o incapacitados para el trabajo", "Menores de veintiún años o incapacitados para el trabajo", "De cualquier edad"]'::jsonb,2,'Art. 224.1 TRLGSS','Puede extenderse hasta los 25 años si el huérfano no trabaja o sus ingresos son inferiores a determinados límites.',null),
('11-6d61f0176a','aux-cm',11,'Están comprendidos en el sistema de la Seguridad Social, a efectos de las prestaciones contributivas, los trabajadores por cuenta propia o autónomos:','["Mayores de dieciocho años", "Mayores de dieciséis años", "Mayores de veintiún años", "De cualquier edad"]'::jsonb,0,'Art. 7.1 b) TRLGSS','El art. 7.1 enumera los incluidos en el campo de aplicación contributivo.',null),
('15-851636b89c','aux-cm',15,'Según la Ley 6/2023, las infracciones muy graves prescriben a los:','["Cinco años", "Diez años", "Seis meses", "Tres años"]'::jsonb,1,'Art. 113.1 Ley 6/2023 CM','Las graves a los tres años y las leves a los seis meses.',null),
('14-592150912c','aux-cm',14,'Según el Decreto 21/2002, las sugerencias y reclamaciones:','["Tienen naturaleza de recurso de alzada", "No tienen la calificación de recurso administrativo y su presentación no suspende los plazos", "No tienen la calificación de recurso, pero su presentación suspende los plazos de los procedimientos", "Suspenden los plazos de recurso"]'::jsonb,1,'Art. 29.2 Decreto 21/2002 CM','No condicionan el ejercicio de otras acciones.',null),
('9-7324f81874','aux-cm',9,'En los contratos de las Administraciones Públicas, el pago aplazado del precio:','["Está prohibido, salvo excepciones como el arrendamiento financiero", "Está permitido siempre que lo acepte el contratista", "Solo se permite en contratos menores y en los de suministro de bienes", "Es obligatorio en los contratos de obras de valor estimado superior a 5.000.000 de euros"]'::jsonb,0,'Art. 102.8 LCSP','Se prohíbe salvo los supuestos legalmente previstos.',null),
('3-9ad78943ae','aux-cm',3,'Según el art. 2 de la Ley 1/1983, el Presidente de la Comunidad ostenta:','["La suprema representación de la Comunidad Autónoma y la ordinaria del Estado en ella", "La jefatura del Consejo de Gobierno, pero no la representación del Estado", "La representación ordinaria de la Comunidad y la suprema del Estado en ella", "La presidencia de la Asamblea"]'::jsonb,0,'Art. 2 Ley 1/1983','Así lo establece el art. 2.',null),
('8-459d0c0d38','aux-cm',8,'El derecho al olvido en búsquedas de Internet permite pedir a los motores de búsqueda:','["Que eliminen de los resultados de una búsqueda por el nombre los enlaces a información inadecuada, inexacta, no pertinente, no actualizada o excesiva", "Que paguen una indemnización automática", "Que borren la página web original en todo caso, junto con todas sus copias y enlaces, aunque la información sea exacta, pertinente y actualizada y su difusión sea lícita", "Que cierren la cuenta del usuario"]'::jsonb,0,'Art. 93.1 LO 3/2018','Es el derecho al olvido frente a buscadores.',null),
('3-c55c170c21','aux-cm',3,'Corresponde al Presidente, como Presidente del Consejo de Gobierno, resolver:','["Los conflictos de competencias entre las distintas Consejerías", "Los recursos contencioso-administrativos", "Los conflictos de competencias entre la Comunidad y los municipios de su territorio", "Los recursos de amparo y los conflictos con otras Comunidades Autónomas"]'::jsonb,0,'Art. 9 e) Ley 1/1983','Es una atribución presidencial indelegable.',null),
('8-509d3507a9','aux-cm',8,'El acceso a los contenidos gestionados por prestadores de servicios digitales de personas fallecidas se regula en la LO 3/2018 como:','["Testamento digital", "Herencia yacente", "Derecho de rectificación", "Derecho de portabilidad"]'::jsonb,0,'Art. 96 LO 3/2018','Salvo que el fallecido lo hubiese prohibido expresamente.',null),
('8-1bee3efbfe','aux-cm',8,'En ningún caso se admitirá la instalación de sistemas de grabación de sonidos o videovigilancia en:','["Las entradas de los edificios", "Los aparcamientos", "Lugares destinados al descanso o esparcimiento de los trabajadores, como vestuarios, aseos o comedores", "Las zonas de caja y de atención al público, aunque se informe previamente a los trabajadores"]'::jsonb,2,'Art. 89.2 LO 3/2018','Protección de la intimidad en el trabajo.',null),
('12-9a81717fbf','aux-cm',12,'Según el principio de especialidad cualitativa, los créditos para gastos:','["Solo pueden gastarse en gastos de personal", "Se destinan a lo que decida cada gestor dentro de su sección presupuestaria, sin vinculación a una finalidad concreta", "Se destinarán exclusivamente a la finalidad específica para la que hayan sido autorizados", "Se destinarán a la finalidad para la que hayan sido autorizados o a cualquier otra del mismo capítulo"]'::jsonb,2,'Art. 73.1 Ley 5/2025 CM','La especialidad cuantitativa impide comprometer gasto por encima del crédito (art. 73.3).',null),
('8-7e949fb53b','aux-cm',8,'En los sistemas de información crediticia, los datos solo pueden mantenerse mientras persista el incumplimiento, con el límite máximo de:','["Cinco años desde la fecha de vencimiento de la obligación", "Diez años", "Un año", "Seis años desde la fecha de inclusión en el sistema"]'::jsonb,0,'Art. 20.1 d) LO 3/2018','Límite temporal de los ficheros de morosos.',null),
('3-6c70da6a3c','aux-cm',3,'Según el art. 37.2 de la Ley 1/1983, la actuación de la Administración de la Comunidad se rige, entre otros, por los principios de:','["Objetividad, publicidad, celeridad, eficacia y economía", "Centralización, jerarquía, unidad de mando y reserva de las actuaciones", "Secreto y discrecionalidad", "Jerarquía, reserva de las actuaciones y libre arbitrio del órgano"]'::jsonb,0,'Art. 37.2 Ley 1/1983','Son principios de actuación administrativa.',null),
('8-460efe5388','aux-cm',8,'Quienes pretendan realizar comunicaciones de mercadotecnia directa deben consultar previamente:','["El censo electoral", "El Registro Civil", "El padrón municipal de habitantes y el censo de empresas", "Los sistemas de exclusión publicitaria"]'::jsonb,3,'Art. 23.4 LO 3/2018','Salvo que el afectado haya prestado su consentimiento a recibirlas.',null),
('8-b16bdcf7bb','aux-cm',8,'El tratamiento de los datos de un menor de catorce años fundado en el consentimiento solo es lícito si consta:','["El consentimiento del propio menor, si tiene madurez suficiente", "El consentimiento del titular de la patria potestad o tutela", "El consentimiento del centro escolar", "Una autorización judicial en todo caso"]'::jsonb,1,'Art. 7.2 LO 3/2018','A partir de los 14 años el menor puede consentir por sí mismo.',null),
('2-b68df44038','aux-cm',2,'En materia de régimen local, la Comunidad de Madrid tiene, en el marco de la legislación básica del Estado:','["Competencia exclusiva sin límites", "Competencia de desarrollo legislativo, potestad reglamentaria y ejecución", "Competencia de ejecución, pero no de desarrollo legislativo ni de potestad reglamentaria", "Solo competencia de ejecución de la legislación del Estado, sin desarrollo legislativo"]'::jsonb,1,'Art. 27.1 EA','El art. 27 recoge las competencias de desarrollo legislativo.',null),
('3-e39546a2a7','aux-cm',3,'Corresponde al Consejo de Gobierno dictar Decretos legislativos:','["Libremente", "Previa autorización de las Cortes Generales", "Previo dictamen del Tribunal Constitucional", "Previa autorización de la Asamblea"]'::jsonb,3,'Art. 21 e) Ley 1/1983','Es la delegación legislativa autonómica.',null),
('12-96ded15221','aux-cm',12,'Los créditos para gastos que el último día del ejercicio no estén afectados al cumplimiento de obligaciones reconocidas:','["Pasan al fondo de contingencia", "Se transfieren a la Asamblea", "Se incorporan automáticamente al ejercicio siguiente", "Quedarán anulados de pleno derecho"]'::jsonb,3,'Art. 81 Ley 5/2025 CM','Es una manifestación del principio de anualidad.',null),
('12-773099ba1a','aux-cm',12,'Según la Ley 5/2025, son créditos ampliables:','["Los que se relacionen de forma taxativa en la ley de presupuestos", "Los de inversiones reales en todo caso", "Cualquier crédito, a petición motivada del centro gestor y con autorización del Consejero de Hacienda", "Todos los créditos de personal"]'::jsonb,0,'Art. 85.2 Ley 5/2025 CM','La relación es taxativa.',null),
('8-3b72a654e2','aux-cm',8,'Las infracciones muy graves de buen gobierno de la Ley 19/2013 prescriben a los:','["Tres años", "Dos años", "Un año", "Cinco años"]'::jsonb,3,'Art. 32 Ley 19/2013','Las graves a los tres años y las leves al año.',null),
('3-93fb88bdd7','aux-cm',3,'Los Consejeros cesan:','["Solo por moción de censura individual aprobada por la Asamblea", "Por decisión de la Asamblea en todo caso", "Por dimisión aceptada por el Presidente, por cese decretado por el Presidente o por fallecimiento", "Por cese acordado por el Consejo de Gobierno, por dimisión aceptada por la Asamblea o por fallecimiento"]'::jsonb,2,'Art. 29 Ley 1/1983','También cesan cuando cesa el Presidente que los nombró.',null),
('12-0b46e3d835','aux-cm',12,'Los anticipos de caja fija son, según la Ley 5/2025:','["Créditos extraordinarios", "Préstamos a empleados públicos", "Provisiones de fondos de carácter permanente para atender gastos periódicos o repetitivos, consideradas operaciones extrapresupuestarias", "Provisiones de fondos de carácter puntual para gastos de inversión, que se aplican al presupuesto antes del pago y se consideran operaciones presupuestarias"]'::jsonb,2,'Art. 102 Ley 5/2025 CM','Son operaciones extrapresupuestarias.',null),
('12-0c0e6fedd3','aux-cm',12,'Según la Ley 5/2025, no son embargables los bienes de la Hacienda Pública de la Comunidad:','["Que estén situados en el extranjero", "Que tengan menos de diez años", "Materialmente afectados a un servicio público o a una función pública, entre otros supuestos", "De ningún tipo, salvo los bienes muebles y los derechos de crédito, que son embargables por mandato judicial en todo caso"]'::jsonb,2,'Art. 44 Ley 5/2025 CM','Privilegio de inembargabilidad.',null),
('8-807d9f0801','aux-cm',8,'La prueba del cumplimiento del deber de responder a la solicitud de ejercicio de derechos corresponde a:','["El encargado del tratamiento", "La AEPD", "El responsable del tratamiento", "El afectado"]'::jsonb,2,'Art. 12.4 LO 3/2018','La carga de la prueba recae en el responsable.',null),
('3-2c5e058089','aux-cm',3,'Las reclamaciones previas a la vía judicial civil y laboral en la Comunidad de Madrid las resuelven:','["Los Directores generales", "El Consejo de Gobierno", "El Presidente de la Comunidad", "Los Consejeros respectivos"]'::jsonb,3,'Art. 53.7 Ley 1/1983','Según el art. 53.7 de la Ley 1/1983.',null),
('8-611e4465e7','aux-cm',8,'Entre la información económica que debe publicarse según el art. 8 de la Ley 19/2013 se encuentran:','["Los datos de salud y las bajas laborales de los empleados públicos de cada departamento", "Las nóminas de todos los funcionarios y del personal laboral, con su nombre y puesto de trabajo", "Las declaraciones del IRPF de los ciudadanos", "Las retribuciones percibidas anualmente por los altos cargos y máximos responsables"]'::jsonb,3,'Art. 8.1 f) Ley 19/2013','También contratos, convenios, subvenciones y presupuestos.',null),
('3-276254058f','aux-cm',3,'Según la Ley 1/1983, conoce en única instancia de las reclamaciones económico-administrativas en la Comunidad de Madrid:','["El Tribunal Económico-Administrativo Central", "La Cámara de Cuentas", "La Junta Superior de Hacienda", "El Consejo de Gobierno"]'::jsonb,2,'Art. 54.2 Ley 1/1983','Órgano de la Comunidad para reclamaciones económico-administrativas.',null),
